import java.sql.*;

public class SafeDatabaseAccess {
    public static void getUserData(String userInput) {
        // Using PreparedStatement prevents SQL injection by safely handling parameterized queries.
        String query = "SELECT * FROM users WHERE username = ?";
        try (Connection conn = DriverManager.getConnection("jdbc:mysql://localhost/db", "user", "pass");
             PreparedStatement pstmt = conn.prepareStatement(query)) {
            pstmt.setString(1, userInput);
            try (ResultSet rs = pstmt.executeQuery()) {
                while (rs.next()) {
                    System.out.println(rs.getString("name"));
                }
            }
        } catch (SQLException e) {
            e.printStackTrace();
        }
    }
}
